{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.interest import compound"
  ],
  "tests": [
    {
      "name": "test_compound_two_years_example",
      "intent": "the example from the task: 1000 at 5% for 2 years should be 1102.50",
      "code": "# intent: the example from the task: 1000 at 5% for 2 years should be 1102.50\ndef test_compound_two_years_example():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 2) == Decimal(\"1102.50\")\n"
    },
    {
      "name": "test_compound_one_year",
      "intent": "one year should apply interest exactly once",
      "code": "# intent: one year should apply interest exactly once\ndef test_compound_one_year():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 1) == Decimal(\"1050.00\")\n"
    },
    {
      "name": "test_compound_zero_years",
      "intent": "zero years returns the principal unchanged",
      "code": "# intent: zero years returns the principal unchanged\ndef test_compound_zero_years():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 0) == Decimal(\"1000.00\")\n"
    },
    {
      "name": "test_compound_three_years",
      "intent": "three years compounds three times, not two",
      "code": "# intent: three years compounds three times, not two\ndef test_compound_three_years():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 3) == Decimal(\"1157.63\")\n"
    },
    {
      "name": "test_compound_negative_years_raises",
      "intent": "negative years are invalid and raise ValueError",
      "code": "# intent: negative years are invalid and raise ValueError\ndef test_compound_negative_years_raises():\n    with pytest.raises(ValueError):\n        compound(Decimal(\"1000.00\"), Decimal(\"5\"), -1)\n"
    },
    {
      "name": "test_compound_rounding_to_cents",
      "intent": "result is rounded to cents using half-up",
      "code": "# intent: result is rounded to cents using half-up\ndef test_compound_rounding_to_cents():\n    assert compound(Decimal(\"100.00\"), Decimal(\"10\"), 1) == Decimal(\"110.00\")\n    assert compound(Decimal(\"100.00\"), Decimal(\"5\"), 1) == Decimal(\"105.00\")\n    assert compound(Decimal(\"100.00\"), Decimal(\"1\"), 1) == Decimal(\"101.00\")\n"
    }
  ]
}
